# vbox_sync.ps1 -- keep the VirtualBox disk containers in step with the raw
# images this repo builds.
#
# WHY THIS EXISTS (read before changing it)
# -----------------------------------------
# build/os_v2_vbox.vdi and build/data_vbox.vdi are REAL VirtualBox VDI
# containers, not copies of the raw .img files:
#     header at 0x00: "<<< Oracle VirtualBox Disk Image >>>"
#     signature 0x40: 0xBEDA107F   type: 1 (dynamic)   cbBlock: 1 MiB
# so `cp build/os_v2.img build/os_v2_vbox.vdi` produces a file VirtualBox
# refuses to open.  They used to be regenerated by hand, which is exactly how
# they drifted: on 2026-11-06 a freshly built build/os_v2.img (13:48) sat next
# to a 11:31 vdi, the VM booted the stale one, and every fix merged after
# 11:31 appeared to be missing inside VirtualBox.
#
# The authoritative converter is VBoxManage, which only exists on Windows.
# This script detaches the medium, converts, and re-attaches, so the VM keeps
# booting the same disk path with the freshly built payload.
#
# Usage (from the Windows host):
#     pwsh -File tools\vbox_sync.ps1
#     pwsh -File tools\vbox_sync.ps1 -VmName NexOS -WhatIf
#
param(
    [string]$VmName   = 'NexOS',
    [string]$RepoRoot = '',
    [switch]$WhatIf
)

# VBoxManage writes its conversion progress to STDERR.  Under Windows
# PowerShell 5.1 a native command's stderr becomes an ErrorRecord, and with
# 'Stop' that aborts the script at convertfromraw (leaving the VM on the old
# disk).  Every VBoxManage call below checks $LASTEXITCODE explicitly instead.
$ErrorActionPreference = 'Continue'

function Find-VBoxManage {
    $candidates = @(
        'C:\Program Files\Oracle\VBoxManage.exe',
        'C:\Program Files\Oracle\VirtualBox\VBoxManage.exe'
    )
    foreach ($c in $candidates) { if (Test-Path $c) { return $c } }
    $cmd = Get-Command VBoxManage.exe -ErrorAction SilentlyContinue
    if ($cmd) { return $cmd.Source }
    throw 'VBoxManage.exe not found (looked in C:\Program Files\Oracle)'
}

if (-not $RepoRoot) {
    # this script lives in <repo>\tools
    $RepoRoot = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)
}
$raw = Join-Path $RepoRoot 'build\os_v2.img'
$vdi = Join-Path $RepoRoot 'build\os_v2_vbox.vdi'

if (-not (Test-Path $raw)) { throw "missing $raw -- run 'make' first" }
if (-not (Test-Path $vdi)) { throw "missing $vdi -- create the VM disk once, then re-run" }

$VBoxManage = Find-VBoxManage
Write-Host "[vbox] VBoxManage: $VBoxManage"
Write-Host ("[vbox] raw : {0}  {1:N0} bytes  {2}" -f $raw, (Get-Item $raw).Length, (Get-Item $raw).LastWriteTime)
Write-Host ("[vbox] vdi : {0}  {1:N0} bytes  {2}" -f $vdi, (Get-Item $vdi).Length, (Get-Item $vdi).LastWriteTime)

# --- refuse to touch a running VM: converting under a live VM corrupts both ---
$running = & $VBoxManage list runningvms
if ($running -match [regex]::Escape('"' + $VmName + '"')) {
    throw "VM '$VmName' is RUNNING -- power it off first (converting a medium in use corrupts it)"
}

# --- 1) detach so VBoxManage will let us replace the file ---------------------
$attachedPath = $null
$info = & $VBoxManage showvminfo $VmName --machinereadable
foreach ($line in $info) {
    if ($line -match '^"IDE-0-0"="(.+)"') {
        # --machinereadable escapes backslashes as "\\".  Keep the last
        # non-"none" value: some VirtualBox versions also emit a stale
        # "none" line for the same port.
        $candidate = $Matches[1].Replace('\\', '\').Trim()
        if ($candidate -ne 'none') { $attachedPath = $candidate }
    }
}
# Whether a disk is attached at all -- NOT whether the path string matched.
# VirtualBox can also drop the attachment when the file under a registered
# medium is replaced, so the final step re-attaches unconditionally anyway.
$attached = ($attachedPath -and $attachedPath -ne 'none')
Write-Host "[vbox] attached as IDE-0-0: $attached ($attachedPath)"
if ($WhatIf) {
    Write-Host '[vbox] -WhatIf: would detach, convert and re-attach'
    return
}
if ($attached) {
    & $VBoxManage storageattach $VmName --storagectl IDE --port 0 --device 0 --type hdd --medium none
    if ($LASTEXITCODE -ne 0) { throw "storageattach (detach) failed rc=$LASTEXITCODE" }
}

# --- 2) convert the freshly built raw image into a VDI ----------------------
# Convert under a temp NAME, then swap: a half-written VDI must never be left
# where the VM expects a bootable disk.
#
# The UUID MATTERS.  VirtualBox stores the attached medium's UUID in
# ~/.VirtualBox/VirtualBox.xml (the media registry) and refuses to open a file
# whose header UUID differs, reporting "inaccessible".  convertfromraw always
# invents a fresh UUID, so the first version of this script replaced the file
# and left the VM with a disk it would not open.  Read the old UUID first and
# pass it back in, so the converted container keeps its identity and the
# registry entry stays valid.
$oldUuid = $null
foreach ($line in (& $VBoxManage showmediuminfo disk $vdi 2>$null)) {
    if ($line -match '^UUID:\s+([0-9a-fA-F-]+)') { $oldUuid = $Matches[1]; break }
}
if (-not $oldUuid) { throw "could not read the UUID of $vdi (needed to keep the VM attachment valid)" }
Write-Host "[vbox] keeping medium UUID: $oldUuid"

$tmp = "$vdi.new.vdi"
if (Test-Path $tmp) { Remove-Item $tmp -Force }
& $VBoxManage convertfromraw $raw $tmp --format VDI 2>&1 | Out-Null
if ($LASTEXITCODE -ne 0) { throw "convertfromraw failed rc=$LASTEXITCODE" }
if (-not (Test-Path $tmp)) { throw 'convertfromraw produced no file' }
& $VBoxManage internalcommands sethduuid $tmp $oldUuid 2>&1 | Out-Null
if ($LASTEXITCODE -ne 0) { throw "sethduuid failed rc=$LASTEXITCODE (the VM would report the disk inaccessible)" }

# --- 3) swap in the new container and ALWAYS re-attach -------------------
# Do not gate this on the probe above: a replaced file can make VirtualBox
# report the medium as detached, and leaving the VM diskless is worse than
# re-attaching a disk that was already attached.
$backup = "$vdi.prev"
if (Test-Path $backup) { Remove-Item $backup -Force }
Move-Item -Path $vdi -Destination $backup -Force
Move-Item -Path $tmp -Destination $vdi -Force
Write-Host ("[vbox] vdi rebuilt: {0:N0} bytes (previous kept as {1})" -f (Get-Item $vdi).Length, $backup)

& $VBoxManage storageattach $VmName --storagectl IDE --port 0 --device 0 --type hdd --medium $vdi
if ($LASTEXITCODE -ne 0) {
    # never leave the VM diskless: put the old container back
    Move-Item -Path $vdi -Destination "$vdi.failed" -Force
    Move-Item -Path $backup -Destination $vdi -Force
    & $VBoxManage storageattach $VmName --storagectl IDE --port 0 --device 0 --type hdd --medium $vdi
    throw "storageattach (re-attach) failed rc=$LASTEXITCODE -- restored the previous container"
}
Write-Host '[vbox] done: VM disk now contains the current build'
